// Zegar 1 przepuszczamy tylko w godzinach szkolnych.
// Po 15:00 pracuje zegar 2 (co godzinę do 21:00), w nocy 22–7 cisza.
const OD = 7;   // od tej godziny
const DO = 15;  // do tej godziny (bez niej)

const teraz = new Date();
const godz = teraz.toLocaleTimeString('pl-PL', { hour: '2-digit', minute: '2-digit' });
if (teraz.getHours() >= OD && teraz.getHours() < DO) {
    node.status({ fill: 'green', shape: 'dot', text: 'sprawdzam · ' + godz });
    return msg;
}
node.status({ fill: 'grey', shape: 'ring', text: 'poza ' + OD + '–' + DO + ' · ' + godz });
return null;

// Wariant A – obiekt JSON dla bramki SMS: { do, tresc, od, flash }
const NUMERY = '48600000000';   // numer odbiorcy; kilka po przecinku: '48600000000,48600000001'
const NADAWCA = 'DZIENNIK';     // pole „od” – nazwa nadawcy SMS

msg.payload = {
    do: NUMERY,
    tresc: msg.payload.tekst,
    od: NADAWCA,
    flash: false
};
return msg;
